export function createOnlineClient({getToken,fetcher=fetch,onChange=()=>{},interval=3000,timeout=15000,timer=setTimeout,cancel=clearTimeout}={}){
 let identity=null,epoch=0,handle=null,controller=null,active=false,reading=false;const state={room:null,busy:false,connected:false,error:null,loaded:false};
 const emit=()=>onChange(structuredClone(state));
 const later=()=>{cancel(handle);if(active&&identity)handle=timer(()=>{void refresh();},interval);};
 async function request(body,code){const ownController=new AbortController();controller=ownController;const limit=timer(()=>ownController.abort(),timeout);try{const token=await Promise.race([getToken(),new Promise((_,reject)=>ownController.signal.addEventListener('abort',()=>reject(new DOMException('Aborted','AbortError')),{once:true}))]);const url='/api/duel'+(!body&&code?'?code='+encodeURIComponent(code):''),r=await fetcher(url,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify({schemaVersion:1,...body}):undefined,cache:'no-store',credentials:'omit',signal:ownController.signal});let data;try{data=await r.json();}catch{throw Error('対戦サーバーの応答を読み取れません。再接続してください。');}if(!r.ok)throw Object.assign(Error(data.message||'対戦サーバーに接続できません。'),{code:data.error});if(data.room&&data.room.schemaVersion!==1)throw Error('アプリを再読込してください。');return data.room;}finally{cancel(limit);if(controller===ownController)controller=null;}}
 async function run(body,code){if(!identity||state.busy)return null;if(reading){if(!body)return null;epoch++;controller?.abort();reading=false;cancel(handle);}const generation=epoch,foreground=!!body||!state.loaded;let changed=false;reading=true;if(foreground){state.busy=true;state.error=null;emit();}try{const room=await request(body,code);if(generation!==epoch)return null;changed=JSON.stringify(room)!==JSON.stringify(state.room)||!state.connected||!!state.error;state.room=room;state.connected=true;state.loaded=true;state.error=null;return room;}catch(e){if(generation===epoch){changed=state.connected||state.error!==e.message;state.error=e.name==='AbortError'?'通信の完了を確認できません。「再接続」で盤面を確認してください。':e.message||'通信が切れました。再接続してください。';state.connected=false;}return null;}finally{if(generation===epoch){reading=false;state.busy=false;if(foreground||changed)emit();later();}}}
 async function refresh(){return run(null,state.room?.code);}
 function setIdentity(uid){if(uid===identity)return;epoch++;identity=uid||null;controller?.abort();cancel(handle);reading=false;Object.assign(state,{room:null,busy:false,connected:false,error:null,loaded:false});emit();if(identity&&active)void refresh();}
 function setActive(value){if(active===value)return;active=value;cancel(handle);if(active&&identity&&!state.busy)void refresh();}
 const mutation=(op,body={})=>run({op,requestId:crypto.randomUUID(),...body});
 return{setIdentity,setActive,refresh,getState:()=>structuredClone(state),create:deck=>mutation('create',{deck}),join:(code,deck)=>mutation('join',{code,deck}),move:(actionId,number)=>mutation('move',{code:state.room?.code,revision:state.room?.revision,actionId,...(number!==undefined?{number}:{})}),resign:()=>mutation('resign',{code:state.room?.code,revision:state.room?.revision}),cancel:()=>mutation('cancel',{code:state.room?.code,revision:state.room?.revision}),clear(){state.room=null;emit();},dispose(){epoch++;identity=null;active=false;controller?.abort();cancel(handle);}};
}
